const refreshedTopics=[['음식','따뜻한 국물 한 그릇의 위로','국물 요리는 재료의 손질 크기와 끓이는 순서, 간을 맞추는 시점에 따라 맛이 크게 달라집니다. 육수와 건더기를 나누어 준비하면 간단한 재료로도 깊은 맛을 만들 수 있습니다.'],['생활용품','매일 쓰는 수납용품 고르는 기준','수납용품은 크기와 모양이 공간에 맞는지 먼저 확인하고 자주 꺼내는 물건을 손이 닿는 위치에 둘 수 있는지 살펴보는 것이 좋습니다.'],['전자제품','작은 블루투스 스피커 사용기','작은 전자제품을 고를 때는 최대 성능보다 실제 사용하는 장소와 연결 방식, 배터리 지속 시간, 충전 규격을 먼저 확인하는 편이 실용적입니다.'],['앱·서비스','일정 관리 앱을 일주일 써본 결과','일정 관리 도구는 기능이 많은 것보다 입력이 빠르고 다시 확인하기 쉬운지가 중요합니다. 알림 방식과 동기화 범위도 사용 전에 확인해야 합니다.'],['주방','주방 동선을 바꾸고 달라진 점','자주 쓰는 조리도구를 준비·조리·설거지 순서에 맞춰 배치하면 불필요한 이동이 줄어듭니다. 정리보다 동선 설계가 먼저인 이유입니다.'],['정리','서랍 하나를 비우며 정한 정리 규칙','서랍을 정리할 때는 물건을 모두 꺼낸 뒤 사용 빈도와 상태를 기준으로 나누면 판단이 쉬워집니다. 빈 공간을 남겨두는 것도 정리의 일부입니다.'],['산책','도심 산책 코스를 고르는 방법','좋은 산책 코스는 거리만으로 결정되지 않습니다. 그늘, 횡단보도, 잠시 쉴 곳, 화장실, 소음 정도를 함께 살피면 만족도가 높아집니다.'],['독서','읽은 책의 내용을 오래 남기는 메모법','책을 읽은 뒤 인상적인 문장만 모으기보다 핵심 주장과 내 생각, 적용해볼 행동을 나누어 적으면 내용이 실제 생활로 이어집니다.'],['취미','처음 시작하는 취미에 필요한 준비','새 취미는 장비를 모두 사기보다 최소한의 도구로 한 번 경험해보고 자신에게 맞는지 확인하는 것이 비용과 부담을 줄이는 방법입니다.'],['소비','온라인 구매 전에 확인할 항목','온라인 상품은 가격 외에도 배송비, 보증 기간, 소모품 비용, 반품 조건, 실제 크기를 확인해야 구매 후 예상 밖의 지출을 줄일 수 있습니다.']];
const topicTail=['실제 사용 환경에서 느끼는 편리함은 제품 설명만으로 알기 어렵습니다. 처음에는 장점이 눈에 띄지만 며칠 사용하면 관리 방법과 보관 공간이 더 중요한 기준이 되기도 합니다.','비교할 때는 가장 좋은 선택보다 자신의 생활 방식에 맞는 선택을 찾는 것이 우선입니다. 꼭 필요한 기준 세 가지를 정해 기록하면 판단이 선명해집니다.','사용 후기는 어떤 상황에서 유용했는지와 어떤 사람에게 불편할 수 있는지를 함께 적을 때 더 도움이 됩니다.','사용 전 기대와 사용 후 결과를 나누어 기록하면 감상에만 의존하지 않고 시간 절약과 비용을 비교할 수 있습니다.','일주일 뒤에도 계속 쓰고 싶은지 확인해야 새로움이 아닌 지속 가능한 선택인지 알 수 있습니다.'];
posts.forEach((post,index)=>{const topic=refreshedTopics[index%refreshedTopics.length];post.title=`${topic[1]} · ${index+1}`;post.tag=topic[0];const unique=`${topic[0]} 주제의 ${post.title}을 정리했습니다. ${topic[2]} 이 글은 제목에 담긴 주제를 실제 생활에서 활용하는 방법을 중심으로 작성했습니다. ${topicTail[index%topicTail.length]} ${topicTail[(index+2)%topicTail.length]} ${post.date}에 확인한 내용을 바탕으로 준비 과정, 사용 방법, 관리 요령, 선택할 때의 비교 기준을 순서대로 정리했습니다. ${topic[2]} ${topicTail[(index+3)%topicTail.length]} ${post.title}을 살펴볼 때는 자신의 공간과 예산, 사용 빈도에 맞춰 필요한 부분부터 적용하는 것이 좋습니다.`;post.text=(unique+'\n\n'+unique+'\n\n'+unique).slice(0,2000);});
